contracts/PriceOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

/**
 * @title PriceOracle
 * @dev Price oracle for mochi that aggregates price feeds from multiple sources
 * @author Your Name
 * @notice Provides price data for tokens across multiple chains
 * @custom:security-contact security@mochi.com
 */
contract PriceOracle is Ownable, Pausable {
    // Price feed mapping: token => price feed address
    mapping(address => address) public priceFeeds;
    
    // Fallback prices for tokens without Chainlink feeds
    mapping(address => uint256) public fallbackPrices;
    
    // Price update events
    event PriceFeedUpdated(address indexed token, address indexed priceFeed);
    event FallbackPriceUpdated(address indexed token, uint256 price);
    event PriceUpdated(address indexed token, uint256 price, uint256 timestamp);
    
    // Minimum price update interval
    uint256 public constant MIN_UPDATE_INTERVAL = 1 hours;
    
    // Last update timestamps
    mapping(address => uint256) public lastUpdateTime;
    
    constructor() Ownable(msg.sender) {}
    
    /**
     * @dev Get the latest price for a token
     */
    function getPrice(address token) external view returns (uint256) {
        require(priceFeeds[token] != address(0) || fallbackPrices[token] > 0, "Oracle: No price feed available");
        
        if (priceFeeds[token] != address(0)) {
            return getChainlinkPrice(token);
        } else {
            return fallbackPrices[token];
        }
    }
    
    // Maximum allowed staleness for Chainlink price (default 1 hour)
    uint256 public constant MAX_PRICE_AGE = 1 hours;

    /**
     * @dev Get price from Chainlink feed with staleness and validity checks (industry standard)
     */
    function getChainlinkPrice(address token) public view returns (uint256) {
        AggregatorV3Interface priceFeed = AggregatorV3Interface(priceFeeds[token]);
        
        (
            uint80 roundId,
            int256 price,
            ,
            uint256 updatedAt,
            uint80 answeredInRound
        ) = priceFeed.latestRoundData();
        
        require(price > 0, "Oracle: Invalid price");
        require(answeredInRound >= roundId, "Oracle: Stale round");
        require(block.timestamp - updatedAt <= MAX_PRICE_AGE, "Oracle: Stale price");
        return uint256(price);
    }
    
    /**
     * @dev Get price with decimals
     */
    function getPriceWithDecimals(address token) external view returns (uint256 price, uint8 decimals) {
        if (priceFeeds[token] != address(0)) {
            AggregatorV3Interface priceFeed = AggregatorV3Interface(priceFeeds[token]);
            decimals = priceFeed.decimals();
            price = getChainlinkPrice(token);
        } else {
            decimals = 8; // Default to 8 decimals
            price = fallbackPrices[token];
        }
    }
    
    /**
     * @dev Set Chainlink price feed for a token
     */
    function setPriceFeed(address token, address priceFeed) external onlyOwner {
        require(priceFeed != address(0), "Oracle: Invalid price feed address");
        priceFeeds[token] = priceFeed;
        emit PriceFeedUpdated(token, priceFeed);
    }
    
    /**
     * @dev Set fallback price for a token
     */
    function setFallbackPrice(address token, uint256 price) external onlyOwner {
        require(price > 0, "Oracle: Invalid price");
        fallbackPrices[token] = price;
        lastUpdateTime[token] = block.timestamp;
        emit FallbackPriceUpdated(token, price);
        emit PriceUpdated(token, price, block.timestamp);
    }
    
    /**
     * @dev Update fallback price (with time check)
     */
    function updateFallbackPrice(address token, uint256 price) external onlyOwner {
        require(price > 0, "Oracle: Invalid price");
        require(
            block.timestamp >= lastUpdateTime[token] + MIN_UPDATE_INTERVAL,
            "Oracle: Update too frequent"
        );
        
        fallbackPrices[token] = price;
        lastUpdateTime[token] = block.timestamp;
        emit FallbackPriceUpdated(token, price);
        emit PriceUpdated(token, price, block.timestamp);
    }
    
    /**
     * @dev Remove price feed for a token
     */
    function removePriceFeed(address token) external onlyOwner {
        priceFeeds[token] = address(0);
        emit PriceFeedUpdated(token, address(0));
    }
    
    /**
     * @dev Check if price feed exists for token
     */
    function hasPriceFeed(address token) external view returns (bool) {
        return priceFeeds[token] != address(0) || fallbackPrices[token] > 0;
    }
    
    /**
     * @dev Get price feed address for token
     */
    function getPriceFeedAddress(address token) external view returns (address) {
        return priceFeeds[token];
    }
    
    /**
     * @dev Pause oracle operations
     */
    function pause() external onlyOwner {
        _pause();
    }
    
    /**
     * @dev Unpause oracle operations
     */
    function unpause() external onlyOwner {
        _unpause();
    }
    
    /**
     * @dev Get multiple prices at once
     */
    function getMultiplePrices(address[] calldata tokens) external view returns (uint256[] memory prices) {
        prices = new uint256[](tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            prices[i] = this.getPrice(tokens[i]);
        }
    }
    
    /**
     * @dev Calculate price impact for a swap
     */
    function calculatePriceImpact(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut
    ) external view returns (uint256 impact) {
        uint256 priceIn = this.getPrice(tokenIn);
        uint256 priceOut = this.getPrice(tokenOut);
        
        uint256 expectedOut = (amountIn * priceIn) / priceOut;
        if (expectedOut > amountOut) {
            impact = ((expectedOut - amountOut) * 10000) / expectedOut; // Basis points
        }
    }
}

contracts/TokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./TokenStructs.sol";

/**
 * @title TokenFactory
 * @dev Professional token factory using EIP-1167 minimal proxy pattern
 * Supports custom security configurations with all available security features
 * Industry standard implementation following OpenZeppelin best practices
 */
contract TokenFactory is Ownable, ReentrancyGuard, Pausable {
    using Clones for address;
    using SafeERC20 for IERC20;
    
    // Plan enumeration (for service fee calculation)
    enum Plan { Basic, Professional, Enterprise }
    
    // Network-aware service fee mapping
    mapping(uint256 => mapping(Plan => uint256)) public networkServiceFees;
    
    // Platform wallet that receives service fees
    address public immutable platformWallet;
    
    // ERC20 implementation/template address
    address public implementation;
    
    // Deployed tokens tracking
    mapping(address => bool) public deployedTokens;
    address[] public allDeployedTokens;
    
    // Token metadata tracking
    using TokenStructs for *;
    mapping(address => TokenStructs.TokenMetadata) public tokenMetadata;
    
    // Token ownership tracking
    mapping(address => address) public tokenOwners;
    
    // Factory statistics
    uint256 public totalTokensDeployed;
    uint256 public totalServiceFeesCollected;
    
    // Events
    event TokenDeployed(
        address indexed tokenAddress,
        address indexed owner,
        string name,
        string symbol,
        Plan plan,
        uint256 serviceFee,
        uint256 chainId,
        uint256 timestamp
    );
    
    event ServiceFeeUpdated(
        uint256 indexed chainId,
        Plan plan,
        uint256 oldFee,
        uint256 newFee,
        address indexed updater
    );
    
    event ImplementationUpdated(
        address indexed oldImplementation,
        address indexed newImplementation,
        address indexed updater
    );
    
    event PlatformWalletUpdated(
        address indexed oldWallet,
        address indexed newWallet,
        address indexed updater
    );
    
    event FactoryPaused(address indexed pauser);
    event FactoryUnpaused(address indexed unpauser);
    
    /**
     * @dev Constructor sets up the factory with network-specific service fees
     * @param _platformWallet Address that receives service fees
     * @param _implementation Address of the ERC20 implementation/template contract
     */
    constructor(address _platformWallet, address _implementation) Ownable(msg.sender) {
        require(_platformWallet != address(0), "TokenFactory: Invalid platform wallet");
        require(_implementation != address(0), "TokenFactory: Invalid implementation address");
        
        platformWallet = _platformWallet;
        implementation = _implementation;
        
        _initializeServiceFees();
    }
    
    /**
     * @dev Initialize service fees for all supported networks
     * Competitive pricing based on network gas costs and market rates
     */
    function _initializeServiceFees() internal {
        // Ethereum Mainnet
        networkServiceFees[1][Plan.Basic] = 0.05 ether;        // ~$100-150
        networkServiceFees[1][Plan.Professional] = 0.15 ether;  // ~$300-450
        networkServiceFees[1][Plan.Enterprise] = 0.3 ether;     // ~$600-900
        
        // Polygon
        networkServiceFees[137][Plan.Basic] = 25 * 10**18;      // 25 MATIC (~$20-30)
        networkServiceFees[137][Plan.Professional] = 75 * 10**18; // 75 MATIC (~$60-90)
        networkServiceFees[137][Plan.Enterprise] = 150 * 10**18;  // 150 MATIC (~$120-180)
        
        // BSC
        networkServiceFees[56][Plan.Basic] = 0.05 * 10**18;     // 0.05 BNB (~$15-25)
        networkServiceFees[56][Plan.Professional] = 0.15 * 10**18; // 0.15 BNB (~$45-75)
        networkServiceFees[56][Plan.Enterprise] = 0.3 * 10**18;    // 0.3 BNB (~$90-150)
        
        // Arbitrum
        networkServiceFees[42161][Plan.Basic] = 0.01 ether;     // ~$20-30
        networkServiceFees[42161][Plan.Professional] = 0.03 ether; // ~$60-90
        networkServiceFees[42161][Plan.Enterprise] = 0.06 ether;   // ~$120-180
        
        // Optimism
        networkServiceFees[10][Plan.Basic] = 0.015 ether;       // ~$30-45
        networkServiceFees[10][Plan.Professional] = 0.045 ether; // ~$90-135
        networkServiceFees[10][Plan.Enterprise] = 0.09 ether;    // ~$180-270
        
        // Base
        networkServiceFees[8453][Plan.Basic] = 0.01 ether;      // ~$20-30
        networkServiceFees[8453][Plan.Professional] = 0.03 ether; // ~$60-90
        networkServiceFees[8453][Plan.Enterprise] = 0.06 ether;   // ~$120-180
        
        // Testnets (reduced fees for testing)
        networkServiceFees[11155111][Plan.Basic] = 0.001 ether;     // Sepolia
        networkServiceFees[11155111][Plan.Professional] = 0.003 ether;
        networkServiceFees[11155111][Plan.Enterprise] = 0.006 ether;
        
        networkServiceFees[80001][Plan.Basic] = 2 * 10**18;         // Mumbai
        networkServiceFees[80001][Plan.Professional] = 6 * 10**18;
        networkServiceFees[80001][Plan.Enterprise] = 12 * 10**18;
        
        networkServiceFees[97][Plan.Basic] = 0.005 * 10**18;        // BSC Testnet
        networkServiceFees[97][Plan.Professional] = 0.015 * 10**18;
        networkServiceFees[97][Plan.Enterprise] = 0.03 * 10**18;
    }
    
    /**
     * @dev Determine plan based on security features selected
     * @param config The token configuration with security features
     * @return plan The determined plan (Basic, Professional, Enterprise)
     */
    function determinePlan(TokenStructs.TokenConfig memory config) public pure returns (Plan plan) {
        // Enterprise features
        if (config.enableAntiWhale || config.enablePause || config.enableTimelock || config.maxWalletAmount > 0) {
            return Plan.Enterprise;
        }
        // Professional features
        else if (config.enableBlacklist || config.maxTxAmount > 0 || config.enableAntiBot || config.cooldownPeriod > 0) {
            return Plan.Professional;
        }
        // Basic features only
        else {
            return Plan.Basic;
        }
    }
    
    /**
     * @dev Get service fee for a specific network and plan
     * @param chainId The network chain ID
     * @param plan The selected plan
     * @return The service fee in wei
     */
    function getServiceFee(uint256 chainId, Plan plan) public view returns (uint256) {
        uint256 fee = networkServiceFees[chainId][plan];
        if (fee == 0) {
            // Fallback to Ethereum mainnet fees for unsupported networks
            fee = networkServiceFees[1][plan];
        }
        return fee;
    }
    
    /**
     * @dev Deploy a new token with custom security configuration using minimal proxy
     * @param name Token name
     * @param symbol Token symbol
     * @param decimals Token decimals
     * @param initialSupply Initial token supply
     * @param meta Token metadata
     * @param config Custom security configuration
     * @param renounceMint Whether to renounce mint authority
     * @param freezingAuthority Address with freezing authority (if enabled)
     */
    function deployToken(
        string memory name,
        string memory symbol,
        uint8 decimals,
        uint256 initialSupply,
        TokenStructs.TokenMetadata memory meta,
        TokenStructs.TokenConfig memory config,
        bool renounceMint,
        address freezingAuthority
    ) public payable nonReentrant whenNotPaused {
        require(bytes(name).length > 0, "TokenFactory: Name cannot be empty");
        require(bytes(symbol).length > 0, "TokenFactory: Symbol cannot be empty");
        require(decimals <= 18, "TokenFactory: Decimals cannot exceed 18");
        require(initialSupply > 0, "TokenFactory: Initial supply must be greater than 0");
        
        // Validate security configuration
        require(config.maxTxAmount <= initialSupply, "TokenFactory: Max transaction amount cannot exceed total supply");
        require(config.maxWalletAmount <= initialSupply, "TokenFactory: Max wallet amount cannot exceed total supply");
        require(config.cooldownPeriod <= 3600, "TokenFactory: Cooldown period cannot exceed 1 hour");
        require(config.timelockDelay <= 604800, "TokenFactory: Timelock delay cannot exceed 7 days");
        
        uint256 chainId = block.chainid;
        Plan plan = determinePlan(config);
        uint256 requiredFee = getServiceFee(chainId, plan);
        
        require(msg.value == requiredFee, "TokenFactory: Service fee must be exact amount");
        
        // Forward service fee to platform wallet
        (bool success, ) = platformWallet.call{value: msg.value}("");
        require(success, "TokenFactory: Failed to forward service fee");
        
        // Deploy minimal proxy
        address clone = implementation.clone();
        
        // Call initialize on the new proxy with custom configuration
        (bool ok, ) = clone.call(
            abi.encodeWithSignature(
                "initialize(string,string,uint8,uint256,address,(string,string,string,string,string,string,string,string,string),bool,(bool,bool,bool,bool,bool,uint256,uint256,uint256,uint256),address,uint256,uint256,address)",
                name,
                symbol,
                decimals,
                initialSupply,
                freezingAuthority != address(0) ? freezingAuthority : msg.sender, // freezingAuthority
                meta,
                renounceMint,
                config,
                platformWallet,
                requiredFee,
                chainId,
                msg.sender  // initialOwner (the token creator)
            )
        );
        require(ok, "TokenFactory: Initialization failed");
        
        // Track deployed token
        deployedTokens[clone] = true;
        allDeployedTokens.push(clone);
        
        // Store token metadata with owner
        tokenMetadata[clone] = meta;
        tokenOwners[clone] = msg.sender;
        
        // Update statistics
        totalTokensDeployed++;
        totalServiceFeesCollected += requiredFee;
        
        // Emit deployment event
        emit TokenDeployed(
            clone,
            msg.sender,
            name,
            symbol,
            plan,
            requiredFee,
            chainId,
            block.timestamp
        );
    }
    
    /**
     * @dev Deploy a new token with plan selection (legacy function for backward compatibility)
     * @param name Token name
     * @param symbol Token symbol
     * @param decimals Token decimals
     * @param initialSupply Initial token supply
     * @param meta Token metadata
     * @param plan Selected plan (Basic, Professional, Enterprise)
     * @param renounceMint Whether to renounce mint authority
     */
    function deployTokenWithPlan(
        string memory name,
        string memory symbol,
        uint8 decimals,
        uint256 initialSupply,
        TokenStructs.TokenMetadata memory meta,
        Plan plan,
        bool renounceMint
    ) external payable nonReentrant whenNotPaused {
        require(bytes(name).length > 0, "TokenFactory: Name cannot be empty");
        require(bytes(symbol).length > 0, "TokenFactory: Symbol cannot be empty");
        require(decimals <= 18, "TokenFactory: Decimals cannot exceed 18");
        require(initialSupply > 0, "TokenFactory: Initial supply must be greater than 0");
        require(plan <= Plan.Enterprise, "TokenFactory: Invalid plan");
        
        // Create configuration based on plan
        TokenStructs.TokenConfig memory config;
        
        if (plan == Plan.Basic) {
            config = TokenStructs.TokenConfig({
                enableBlacklist: false,
                enableAntiBot: false,
                enableAntiWhale: false,
                enablePause: false,
                enableTimelock: false,
                maxTxAmount: 0,
                maxWalletAmount: 0,
                cooldownPeriod: 0,
                timelockDelay: 0
            });
        } else if (plan == Plan.Professional) {
            config = TokenStructs.TokenConfig({
                enableBlacklist: true,
                enableAntiBot: true,
                enableAntiWhale: false,
                enablePause: false,
                enableTimelock: false,
                maxTxAmount: 10000 * 10**18, // 10k max tx
                maxWalletAmount: 0,
                cooldownPeriod: 30, // 30 seconds
                timelockDelay: 0
            });
        } else if (plan == Plan.Enterprise) {
            config = TokenStructs.TokenConfig({
                enableBlacklist: true,
                enableAntiBot: true,
                enableAntiWhale: true,
                enablePause: true,
                enableTimelock: true,
                maxTxAmount: 5000 * 10**18, // 5k max tx
                maxWalletAmount: 50000 * 10**18, // 50k max wallet
                cooldownPeriod: 60, // 60 seconds
                timelockDelay: 86400 // 24 hours
            });
        }
        
        // Deploy using the custom configuration function
        deployToken(
            name,
            symbol,
            decimals,
            initialSupply,
            meta,
            config,
            renounceMint,
            msg.sender
        );
    }
    
    /**
     * @dev Get all deployed tokens
     * @return Array of all deployed token addresses
     */
    function getAllDeployedTokens() external view returns (address[] memory) {
        return allDeployedTokens;
    }
    
    /**
     * @dev Get deployed tokens count
     * @return Number of deployed tokens
     */
    function getDeployedTokensCount() external view returns (uint256) {
        return allDeployedTokens.length;
    }
    
    /**
     * @dev Check if an address is a deployed token
     * @param tokenAddress Address to check
     * @return True if the address is a deployed token
     */
    function isDeployedToken(address tokenAddress) external view returns (bool) {
        return deployedTokens[tokenAddress];
    }
    
    /**
     * @dev Get token metadata
     * @param tokenAddress Address of the token
     * @return metadata The token metadata
     */
    function getTokenMetadata(address tokenAddress) external view returns (TokenStructs.TokenMetadata memory) {
        require(deployedTokens[tokenAddress], "TokenFactory: Token not found");
        return tokenMetadata[tokenAddress];
    }
    
    /**
     * @dev Get tokens deployed by a specific owner
     * @param owner Address of the token owner
     * @return Array of token addresses deployed by the owner
     */
    function getTokensByOwner(address owner) external view returns (address[] memory) {
        address[] memory ownerTokens = new address[](allDeployedTokens.length);
        uint256 count = 0;
        
        for (uint256 i = 0; i < allDeployedTokens.length; i++) {
            if (tokenOwners[allDeployedTokens[i]] == owner) {
                ownerTokens[count] = allDeployedTokens[i];
                count++;
            }
        }
        
        // Resize array to actual count
        assembly {
            mstore(ownerTokens, count)
        }
        
        return ownerTokens;
    }
    
    /**
     * @dev Get factory statistics
     * @return _totalTokensDeployed Total number of tokens deployed
     * @return _totalServiceFeesCollected Total service fees collected
     * @return _deployedTokensCount Current number of deployed tokens
     * @return _chainId Current chain ID
     * @return _platformWallet Platform wallet address
     * @return _implementation Implementation contract address
     */
    function getFactoryStats() external view returns (
        uint256 _totalTokensDeployed,
        uint256 _totalServiceFeesCollected,
        uint256 _deployedTokensCount,
        uint256 _chainId,
        address _platformWallet,
        address _implementation
    ) {
        return (
            totalTokensDeployed,
            totalServiceFeesCollected,
            allDeployedTokens.length,
            block.chainid,
            platformWallet,
            implementation
        );
    }
    
    // ============ ADMIN FUNCTIONS ============
    
    /**
     * @dev Update service fee for a specific network and plan (owner only)
     * @param chainId The network chain ID
     * @param plan The plan to update
     * @param newFee The new service fee
     */
    function updateServiceFee(uint256 chainId, Plan plan, uint256 newFee) external onlyOwner {
        require(plan <= Plan.Enterprise, "TokenFactory: Invalid plan");
        require(newFee > 0, "TokenFactory: Fee must be greater than 0");
        
        uint256 oldFee = networkServiceFees[chainId][plan];
        networkServiceFees[chainId][plan] = newFee;
        
        emit ServiceFeeUpdated(chainId, plan, oldFee, newFee, msg.sender);
    }
    
    /**
     * @dev Update implementation address (owner only)
     * @param newImplementation New implementation address
     */
    function updateImplementation(address newImplementation) external onlyOwner {
        require(newImplementation != address(0), "TokenFactory: Invalid implementation address");
        
        address oldImplementation = implementation;
        implementation = newImplementation;
        
        emit ImplementationUpdated(oldImplementation, newImplementation, msg.sender);
    }
    
    /**
     * @dev Pause factory (owner only)
     */
    function pause() external onlyOwner {
        _pause();
        emit FactoryPaused(msg.sender);
    }
    
    /**
     * @dev Unpause factory (owner only)
     */
    function unpause() external onlyOwner {
        _unpause();
        emit FactoryUnpaused(msg.sender);
    }
    
    /**
     * @dev Emergency function to recover stuck tokens (owner only)
     * @param tokenAddress Address of the token to recover
     * @param to Address to send tokens to
     * @param amount Amount to recover
     */
    function emergencyRecover(address tokenAddress, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "TokenFactory: Invalid recipient address");
        require(amount > 0, "TokenFactory: Amount must be greater than 0");
        require(tokenAddress != address(0), "TokenFactory: Use emergencyRecoverETH for ETH");
        
        IERC20(tokenAddress).safeTransfer(to, amount);
    }
    
    /**
     * @dev Emergency function to recover stuck ETH (owner only)
     * @param to Address to send ETH to
     * @param amount Amount to recover
     */
    function emergencyRecoverETH(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "TokenFactory: Invalid recipient address");
        require(amount > 0, "TokenFactory: Amount must be greater than 0");
        require(amount <= address(this).balance, "TokenFactory: Insufficient balance");
        
        (bool success, ) = to.call{value: amount}("");
        require(success, "TokenFactory: ETH transfer failed");
    }
}

contracts/TokenImplementation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./TokenStructs.sol";

/**
 * @title TokenImplementation
 * @dev Implementation contract for ERC20 tokens with comprehensive security features
 * This contract is designed to be used with TokenFactory using EIP-1167 minimal proxy pattern
 * All initialization is done through the initialize function instead of constructor
 */
contract TokenImplementation is ERC20, Ownable, Pausable, ReentrancyGuard {
    uint8 private _decimals;
    // Store name and symbol in our own variables to avoid storage collision
    string private _tokenName;
    string private _tokenSymbol;
    string private _logo;
    string private _website;
    string private _description;
    string private _twitter;
    string private _telegram;
    string private _discord;
    string private _github;
    string private _medium;
    string private _reddit;
    uint256 private _maxTxAmount;
    uint256 private _maxWalletAmount;
    uint256 private _cooldownPeriod;
    uint256 private _timelockDelay;
    
    // Plan-based feature flags
    bool public isProfessionalPlan;
    bool public isEnterprisePlan;
    bool public isInitialized;
    
    address public freezingAuthority;
    address public blacklistAuthority;
    
    bool public mintAuthorityRemoved;
    bool public antiBotEnabled;
    bool public antiWhaleEnabled;
    bool public timelockEnabled;
    bool public maxWalletEnabled;
    
    // Service fee configuration
    address public platformWallet;
    uint256 public serviceFee;
    uint256 public chainId;
    
    // Network-specific service fee mapping
    mapping(uint256 => uint256) private _networkServiceFees;
    
    // Security mappings
    mapping(address => bool) private _frozen;
    mapping(address => bool) private _blacklisted;
    mapping(address => uint256) private _lastTransactionTime;
    mapping(address => bool) private _isExcludedFromLimits;
    
    // Timelock for administrative functions
    mapping(bytes32 => uint256) private _pendingActions;
    
    event Freeze(address indexed account, bool frozen);
    event Blacklist(address indexed account, bool blacklisted);
    event PlanUpgraded(string plan);
    event ServiceFeePaid(address indexed payer, uint256 amount, uint256 chainId);
    event CooldownUpdated(uint256 newCooldown);
    event MaxWalletUpdated(uint256 newMaxWallet);
    event TimelockActionScheduled(bytes32 indexed actionId, uint256 executeTime);
    event TimelockActionExecuted(bytes32 indexed actionId);
    event TokenInitialized(
        address indexed owner,
        string name,
        string symbol,
        uint8 decimals,
        uint256 initialSupply
    );
    
    // Network service fee configuration
    // These are the expected service fees for each network (in wei)
    // Updated to be competitive with market rates while maintaining profitability
    uint256 private constant ETHEREUM_BASIC_FEE = 0.05 ether; // ~$100-150
    uint256 private constant ETHEREUM_PROFESSIONAL_FEE = 0.15 ether; // ~$300-450
    uint256 private constant ETHEREUM_ENTERPRISE_FEE = 0.3 ether; // ~$600-900
    
    uint256 private constant POLYGON_BASIC_FEE = 25 * 10**18; // 25 MATIC (~$20-30)
    uint256 private constant POLYGON_PROFESSIONAL_FEE = 75 * 10**18; // 75 MATIC (~$60-90)
    uint256 private constant POLYGON_ENTERPRISE_FEE = 150 * 10**18; // 150 MATIC (~$120-180)
    
    uint256 private constant BSC_BASIC_FEE = 0.05 * 10**18; // 0.05 BNB (~$15-25)
    uint256 private constant BSC_PROFESSIONAL_FEE = 0.15 * 10**18; // 0.15 BNB (~$45-75)
    uint256 private constant BSC_ENTERPRISE_FEE = 0.3 * 10**18; // 0.3 BNB (~$90-150)
    
    uint256 private constant ARBITRUM_BASIC_FEE = 0.01 ether; // ~$20-30
    uint256 private constant ARBITRUM_PROFESSIONAL_FEE = 0.03 ether; // ~$60-90
    uint256 private constant ARBITRUM_ENTERPRISE_FEE = 0.06 ether; // ~$120-180
    
    uint256 private constant OPTIMISM_BASIC_FEE = 0.015 ether; // ~$30-45
    uint256 private constant OPTIMISM_PROFESSIONAL_FEE = 0.045 ether; // ~$90-135
    uint256 private constant OPTIMISM_ENTERPRISE_FEE = 0.09 ether; // ~$180-270
    
    uint256 private constant BASE_BASIC_FEE = 0.01 ether; // ~$20-30
    uint256 private constant BASE_PROFESSIONAL_FEE = 0.03 ether; // ~$60-90
    uint256 private constant BASE_ENTERPRISE_FEE = 0.06 ether; // ~$120-180
    
    // Testnet fees (reduced for testing)
    uint256 private constant SEPOLIA_BASIC_FEE = 0.001 ether; // ~$2-3
    uint256 private constant SEPOLIA_PROFESSIONAL_FEE = 0.003 ether; // ~$6-9
    uint256 private constant SEPOLIA_ENTERPRISE_FEE = 0.006 ether; // ~$12-18
    
    uint256 private constant MUMBAI_BASIC_FEE = 2 * 10**18; // 2 MATIC (~$1.60-2.40)
    uint256 private constant MUMBAI_PROFESSIONAL_FEE = 6 * 10**18; // 6 MATIC (~$4.80-7.20)
    uint256 private constant MUMBAI_ENTERPRISE_FEE = 12 * 10**18; // 12 MATIC (~$9.60-14.40)
    
    uint256 private constant BSC_TESTNET_BASIC_FEE = 0.005 * 10**18; // 0.005 tBNB (~$1.50-2.50)
    uint256 private constant BSC_TESTNET_PROFESSIONAL_FEE = 0.015 * 10**18; // 0.015 tBNB (~$4.50-7.50)
    uint256 private constant BSC_TESTNET_ENTERPRISE_FEE = 0.03 * 10**18; // 0.03 tBNB (~$9-15)
    
    // Token metadata struct to reduce stack depth
    using TokenStructs for *;
    
    // Constructor with empty name/symbol - will be set in initialize
    constructor() ERC20("", "") Ownable(msg.sender) {}
    
    function initialize(
        string memory name,
        string memory symbol,
        uint8 decimals_,
        uint256 initialSupply,
        address freezingAuthority_,
        TokenStructs.TokenMetadata memory meta,
        bool renounceMint,
        TokenStructs.TokenConfig memory config,
        address platformWallet_,
        uint256 serviceFee_,
        uint256 chainId_,
        address initialOwner
    ) external {
        require(!isInitialized, "TokenImplementation: Already initialized");
        
        // Set owner if not already set (first initialization)
        if (owner() == address(0)) {
            _transferOwnership(initialOwner);
        } else {
            require(msg.sender == owner(), "TokenImplementation: Only owner can initialize");
        }
        
        isInitialized = true;
        
        // Store name and symbol in our own variables
        _tokenName = name;
        _tokenSymbol = symbol;
        
        _decimals = decimals_;
        _logo = meta.logo;
        _website = meta.website;
        _description = meta.description;
        _twitter = meta.twitter;
        _telegram = meta.telegram;
        _discord = meta.discord;
        _github = meta.github;
        _medium = meta.medium;
        _reddit = meta.reddit;
        _maxTxAmount = config.maxTxAmount;
        _maxWalletAmount = config.maxWalletAmount;
        _cooldownPeriod = config.cooldownPeriod;
        _timelockDelay = config.timelockDelay;
        platformWallet = platformWallet_;
        serviceFee = serviceFee_;
        chainId = chainId_;
        if (config.enableBlacklist || config.maxTxAmount > 0 || config.enableAntiBot || config.cooldownPeriod > 0) {
            isProfessionalPlan = true;
        }
        if (config.enableAntiWhale || config.enablePause || config.enableTimelock || config.maxWalletAmount > 0) {
            isEnterprisePlan = true;
            isProfessionalPlan = true;
        }
        uint256 expectedFee = getExpectedServiceFee(chainId_, isProfessionalPlan, isEnterprisePlan);
        require(serviceFee_ >= expectedFee, "TokenImplementation: Insufficient service fee for this network and plan");
        if (isProfessionalPlan || isEnterprisePlan) {
            freezingAuthority = freezingAuthority_;
            blacklistAuthority = config.enableBlacklist ? initialOwner : address(0);
        }
        antiBotEnabled = config.enableAntiBot;
        antiWhaleEnabled = config.enableAntiWhale;
        maxWalletEnabled = config.maxWalletAmount > 0;
        timelockEnabled = config.enableTimelock;
        _isExcludedFromLimits[initialOwner] = true;
        if (initialSupply > 0) {
            _mint(initialOwner, initialSupply);
        }
        if (renounceMint) {
            mintAuthorityRemoved = true;
        }
        emit TokenInitialized(initialOwner, name, symbol, decimals_, initialSupply);
    }
    
    /**
     * @dev Get the expected service fee for a given network and plan
     * @param networkChainId The chain ID of the network
     * @param isProfessional Whether this is a professional plan
     * @param isEnterprise Whether this is an enterprise plan
     * @return The expected service fee in wei
     */
    function getExpectedServiceFee(uint256 networkChainId, bool isProfessional, bool isEnterprise) public pure returns (uint256) {
        if (isEnterprise) {
            if (networkChainId == 1) return ETHEREUM_ENTERPRISE_FEE;
            if (networkChainId == 137) return POLYGON_ENTERPRISE_FEE;
            if (networkChainId == 56) return BSC_ENTERPRISE_FEE;
            if (networkChainId == 42161) return ARBITRUM_ENTERPRISE_FEE;
            if (networkChainId == 10) return OPTIMISM_ENTERPRISE_FEE;
            if (networkChainId == 8453) return BASE_ENTERPRISE_FEE;
            if (networkChainId == 11155111) return SEPOLIA_ENTERPRISE_FEE;
            if (networkChainId == 80001) return MUMBAI_ENTERPRISE_FEE;
            if (networkChainId == 97) return BSC_TESTNET_ENTERPRISE_FEE;
        } else if (isProfessional) {
            if (networkChainId == 1) return ETHEREUM_PROFESSIONAL_FEE;
            if (networkChainId == 137) return POLYGON_PROFESSIONAL_FEE;
            if (networkChainId == 56) return BSC_PROFESSIONAL_FEE;
            if (networkChainId == 42161) return ARBITRUM_PROFESSIONAL_FEE;
            if (networkChainId == 10) return OPTIMISM_PROFESSIONAL_FEE;
            if (networkChainId == 8453) return BASE_PROFESSIONAL_FEE;
            if (networkChainId == 11155111) return SEPOLIA_PROFESSIONAL_FEE;
            if (networkChainId == 80001) return MUMBAI_PROFESSIONAL_FEE;
            if (networkChainId == 97) return BSC_TESTNET_PROFESSIONAL_FEE;
        } else {
            if (networkChainId == 1) return ETHEREUM_BASIC_FEE;
            if (networkChainId == 137) return POLYGON_BASIC_FEE;
            if (networkChainId == 56) return BSC_BASIC_FEE;
            if (networkChainId == 42161) return ARBITRUM_BASIC_FEE;
            if (networkChainId == 10) return OPTIMISM_BASIC_FEE;
            if (networkChainId == 8453) return BASE_BASIC_FEE;
            if (networkChainId == 11155111) return SEPOLIA_BASIC_FEE;
            if (networkChainId == 80001) return MUMBAI_BASIC_FEE;
            if (networkChainId == 97) return BSC_TESTNET_BASIC_FEE;
        }
        
        // Fallback to Ethereum basic fee for unsupported networks
        return ETHEREUM_BASIC_FEE;
    }
    
    // Modifiers
    modifier onlyFreezingAuthority() {
        require(isProfessionalPlan || isEnterprisePlan, "Freezing not available in basic plan");
        require(msg.sender == freezingAuthority, "Not freezing authority");
        _;
    }
    
    modifier onlyBlacklistAuthority() {
        require(isProfessionalPlan || isEnterprisePlan, "Blacklist not available in basic plan");
        require(msg.sender == blacklistAuthority, "Not blacklist authority");
        _;
    }
    
    modifier notFrozen(address account) {
        if (isProfessionalPlan || isEnterprisePlan) {
            require(!_frozen[account], "Account is frozen");
        }
        _;
    }
    
    modifier notBlacklisted(address account) {
        if (isProfessionalPlan || isEnterprisePlan) {
            require(!_blacklisted[account], "Account is blacklisted");
        }
        _;
    }
    
    modifier onlyEnterprisePlan() {
        require(isEnterprisePlan, "Enterprise plan required");
        _;
    }
    
    modifier checkCooldown() {
        if (antiBotEnabled && (isProfessionalPlan || isEnterprisePlan)) {
            require(
                block.timestamp >= _lastTransactionTime[msg.sender] + _cooldownPeriod,
                "Cooldown period not elapsed"
            );
            _lastTransactionTime[msg.sender] = block.timestamp;
        }
        _;
    }
    
    modifier onlyTimelock() {
        if (timelockEnabled && isEnterprisePlan) {
            require(msg.sender == address(this), "Only timelock can execute");
        }
        _;
    }
    
    // Override transfer functions to include security checks
    function _update(address from, address to, uint256 value) internal virtual override {
        require(!paused(), "Token is paused");
        require(from != address(0) || to != address(0), "Invalid transfer");
        
        // Apply security checks based on plan
        if (from != address(0) && to != address(0)) {
            // Regular transfer
            require(!_frozen[from] && !_frozen[to], "Account is frozen");
            require(!_blacklisted[from] && !_blacklisted[to], "Account is blacklisted");
            
            // Check transaction limits
            if (_maxTxAmount > 0 && !_isExcludedFromLimits[from] && !_isExcludedFromLimits[to]) {
                require(value <= _maxTxAmount, "Transfer amount exceeds max transaction amount");
            }
            
            // Check wallet limits
            if (_maxWalletAmount > 0 && !_isExcludedFromLimits[to]) {
                require(balanceOf(to) + value <= _maxWalletAmount, "Transfer would exceed max wallet amount");
            }
        }
        
        super._update(from, to, value);
    }
    
    // Public view functions
    function name() public view virtual override returns (string memory) {
        return _tokenName;
    }
    
    function symbol() public view virtual override returns (string memory) {
        return _tokenSymbol;
    }
    
    function decimals() public view virtual override returns (uint8) {
        return _decimals;
    }
    
    function logo() public view returns (string memory) {
        return _logo;
    }
    
    function website() public view returns (string memory) {
        return _website;
    }
    
    function description() public view returns (string memory) {
        return _description;
    }
    
    function twitter() public view returns (string memory) {
        return _twitter;
    }
    
    function telegram() public view returns (string memory) {
        return _telegram;
    }
    
    function discord() public view returns (string memory) {
        return _discord;
    }
    
    function github() public view returns (string memory) {
        return _github;
    }
    
    function medium() public view returns (string memory) {
        return _medium;
    }
    
    function reddit() public view returns (string memory) {
        return _reddit;
    }
    
    function maxTxAmount() public view returns (uint256) {
        return _maxTxAmount;
    }
    
    function maxWalletAmount() public view returns (uint256) {
        return _maxWalletAmount;
    }
    
    function cooldownPeriod() public view returns (uint256) {
        return _cooldownPeriod;
    }
    
    function timelockDelay() public view returns (uint256) {
        return _timelockDelay;
    }
    
    // Admin functions
    function mint(address to, uint256 amount) public onlyOwner {
        require(!mintAuthorityRemoved, "Mint authority removed");
        _mint(to, amount);
    }
    
    function removeMintAuthority() public onlyOwner {
        require(!mintAuthorityRemoved, "Mint authority already removed");
        mintAuthorityRemoved = true;
    }
    
    function freeze(address account, bool freezeAccount) public onlyFreezingAuthority returns (bool) {
        require(account != address(0), "Cannot freeze zero address");
        _frozen[account] = freezeAccount;
        emit Freeze(account, freezeAccount);
        return true;
    }
    
    function isFrozen(address account) public view returns (bool) {
        return _frozen[account];
    }
    
    function setFreezingAuthority(address newAuthority) public onlyOwner {
        require(isProfessionalPlan || isEnterprisePlan, "Plan upgrade required");
        freezingAuthority = newAuthority;
    }
    
    function blacklist(address account, bool blacklistAccount) public onlyBlacklistAuthority returns (bool) {
        require(account != address(0), "Cannot blacklist zero address");
        _blacklisted[account] = blacklistAccount;
        emit Blacklist(account, blacklistAccount);
        return true;
    }
    
    function isBlacklisted(address account) public view returns (bool) {
        return _blacklisted[account];
    }
    
    function setBlacklistAuthority(address newAuthority) public onlyOwner {
        require(isProfessionalPlan || isEnterprisePlan, "Plan upgrade required");
        blacklistAuthority = newAuthority;
    }
    
    function setMaxTxAmount(uint256 newMaxTxAmount) public onlyOwner {
        require(isProfessionalPlan || isEnterprisePlan, "Plan upgrade required");
        _maxTxAmount = newMaxTxAmount;
    }
    
    function setMaxWalletAmount(uint256 newMaxWalletAmount) public onlyOwner onlyEnterprisePlan {
        _maxWalletAmount = newMaxWalletAmount;
        maxWalletEnabled = newMaxWalletAmount > 0;
        emit MaxWalletUpdated(newMaxWalletAmount);
    }
    
    function setCooldownPeriod(uint256 newCooldownPeriod) public onlyOwner {
        require(isProfessionalPlan || isEnterprisePlan, "Plan upgrade required");
        _cooldownPeriod = newCooldownPeriod;
        emit CooldownUpdated(newCooldownPeriod);
    }
    
    function excludeFromLimits(address account, bool excluded) public onlyOwner {
        _isExcludedFromLimits[account] = excluded;
    }
    
    function isExcludedFromLimits(address account) public view returns (bool) {
        return _isExcludedFromLimits[account];
    }
    
    // Pause functionality (Enterprise plan only)
    function pause() public onlyOwner onlyEnterprisePlan {
        _pause();
    }
    
    function unpause() public onlyOwner onlyEnterprisePlan {
        _unpause();
    }
    
    // Timelock functionality (Enterprise plan only)
    function scheduleAction(bytes32 actionId, uint256 delay) public onlyOwner onlyEnterprisePlan {
        require(delay >= _timelockDelay, "Delay too short");
        require(_pendingActions[actionId] == 0, "Action already scheduled");
        
        _pendingActions[actionId] = block.timestamp + delay;
        emit TimelockActionScheduled(actionId, block.timestamp + delay);
    }
    
    function executeAction(bytes32 actionId) public onlyOwner onlyEnterprisePlan {
        require(_pendingActions[actionId] > 0, "Action not scheduled");
        require(block.timestamp >= _pendingActions[actionId], "Delay not elapsed");
        
        delete _pendingActions[actionId];
        emit TimelockActionExecuted(actionId);
    }
    
    function getPendingAction(bytes32 actionId) public view returns (uint256) {
        return _pendingActions[actionId];
    }
    
    // Emergency functions
    function emergencyTransfer(address from, address to, uint256 amount) public onlyOwner {
        require(from != address(0) && to != address(0), "Invalid addresses");
        _transfer(from, to, amount);
    }
    
    function emergencyMint(address to, uint256 amount) public onlyOwner {
        require(!mintAuthorityRemoved, "Mint authority removed");
        _mint(to, amount);
    }
    
    // View functions for plan information
    function getPlanInfo() public view returns (
        bool _isProfessionalPlan,
        bool _isEnterprisePlan,
        bool _antiBotEnabled,
        bool _antiWhaleEnabled,
        bool _timelockEnabled,
        bool _maxWalletEnabled,
        uint256 maxTxAmountValue,
        uint256 maxWalletAmountValue,
        uint256 cooldownPeriodValue,
        uint256 timelockDelayValue
    ) {
        return (
            isProfessionalPlan,
            isEnterprisePlan,
            antiBotEnabled,
            antiWhaleEnabled,
            timelockEnabled,
            maxWalletEnabled,
            _maxTxAmount,
            _maxWalletAmount,
            _cooldownPeriod,
            _timelockDelay
        );
    }
}

